<template><view class="page"><view class="head"><text class="eyebrow">绿色行动</text><text class="title">低碳挑战</text><text class="subtitle">每位学生只显示自己的参与进度</text></view><view class="tabs"><text v-for="tab in tabs" :key="tab.key" :class="{selected:current===tab.key}" @tap="current=tab.key">{{tab.label}}</text></view><view v-if="filtered.length" class="challenge-list"><view v-for="item in filtered" :key="item.id" class="challenge-card card"><view class="top-row"><view class="challenge-icon">{{item.icon}}</view><text :class="['status',item.status]">{{statusText(item.status)}}</text></view><text class="challenge-title">{{item.title}}</text><text class="challenge-reward">+{{item.reward}} 积分</text><text class="challenge-desc">{{item.desc}}</text><view class="proof"><text>需要凭证：</text><text>{{item.proof}}</text></view><view class="progress-row"><text>连续进度</text><text>{{item.progress}}/{{item.target}} 天</text></view><view class="progress"><view :style="{width:Math.min(item.progress/item.target*100,100)+'%'}"></view></view><view v-if="item.status==='not_started'" class="primary-btn action" @tap="join(item)">立即开启</view><view v-else-if="item.status==='in_progress'" class="outline-btn action" @tap="continueChallenge(item)">去打卡</view><view v-else class="disabled-btn action">已完成</view></view></view><view v-else class="empty card">暂无对应挑战</view><BottomNav active="challenge"/></view></template>
<script>
import BottomNav from '../../components/BottomNav.vue'
import { toast } from '../../common/mock.js'
const seed=[{id:'meal-7',icon:'🍽',title:'连续7天光盘行动',desc:'连续7天上传餐后餐盘照片，减少食物浪费。',proof:'餐后餐盘照片',reward:100,target:7},{id:'bike-5',icon:'🚲',title:'连续5天骑行',desc:'连续5天完成骑行，记录绿色出行行为。',proof:'骑行现场照片',reward:115,target:5},{id:'cup-3',icon:'🥤',title:'连续3天自带水杯',desc:'连续3天使用可重复水杯，减少一次性塑料。',proof:'当天水杯照片',reward:45,target:3},{id:'sort-3',icon:'♻',title:'垃圾分类达人',desc:'连续3天完成垃圾分类并上传投放现场。',proof:'分类投放照片',reward:60,target:3},{id:'power-5',icon:'💡',title:'节约用电挑战',desc:'连续5天离开房间前关闭电器。',proof:'关闭电器现场照片',reward:80,target:5}]
export default{components:{BottomNav},data(){return{tabs:[{key:'all',label:'全部挑战'},{key:'in_progress',label:'进行中'},{key:'completed',label:'已完成'}],current:'all',list:[]}},computed:{filtered(){return this.current==='all'?this.list:this.list.filter(x=>x.status===this.current)}},onShow(){const session=uni.getStorageSync('user_session')||{};const key='challenge_states_'+(session.id||session.username||'guest');const saved=uni.getStorageSync(key)||{};this.list=seed.map(x=>({...x,progress:0,status:'not_started',...(saved[x.id]||{})}))},methods:{statusText(s){return s==='completed'?'已完成':s==='in_progress'?'进行中':'未开始'},persist(){const session=uni.getStorageSync('user_session')||{};const key='challenge_states_'+(session.id||session.username||'guest');const data={};this.list.forEach(x=>data[x.id]={progress:x.progress,status:x.status});uni.setStorageSync(key,data)},join(item){item.status='in_progress';this.persist();toast('挑战已开启');uni.navigateTo({url:'/pages/personal/challenge-detail?id='+item.id})},continueChallenge(item){uni.navigateTo({url:'/pages/personal/challenge-detail?id='+item.id})}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.tabs{display:flex;gap:16rpx;margin:10rpx 0 26rpx}.tabs text{padding:18rpx 26rpx;border-radius:40rpx;background:#e6e9e8;color:#53615f;font-size:24rpx}.tabs .selected{background:#006d37;color:#fff}.challenge-list{display:flex;flex-direction:column;gap:18rpx}.challenge-card{padding:26rpx}.top-row{display:flex;align-items:center;justify-content:space-between}.challenge-icon{display:flex;align-items:center;justify-content:center;width:70rpx;height:70rpx;border-radius:22rpx;background:#d6e6e3;color:#006d37;font-size:34rpx}.status{padding:8rpx 16rpx;border-radius:22rpx;font-size:21rpx}.status.not_started{background:#eef1ef;color:#68746c}.status.in_progress{background:#dcece3;color:#277a43}.status.completed{background:#d6e6e3;color:#006d37}.challenge-title{display:block;margin-top:18rpx;color:#181c1c;font-size:31rpx;font-weight:700}.challenge-reward{display:block;margin-top:8rpx;color:#347c55;font-size:23rpx}.challenge-desc{display:block;margin-top:12rpx;color:#6d7a6e;font-size:23rpx;line-height:1.5}.proof{display:flex;gap:8rpx;margin-top:16rpx;padding:14rpx 18rpx;border-radius:16rpx;background:#f1f4f3;color:#53615f;font-size:21rpx}.progress-row{display:flex;justify-content:space-between;margin-top:18rpx;color:#6d7a6e;font-size:21rpx}.progress{height:14rpx;margin-top:8rpx;border-radius:20rpx;background:#e6e9e8;overflow:hidden}.progress view{height:100%;border-radius:20rpx;background:#27ae60}.action{width:100%;min-height:70rpx;margin-top:20rpx;border-radius:36rpx;text-align:center;font-size:24rpx}.disabled-btn{display:flex;align-items:center;justify-content:center;background:#e6e9e8;color:#87938b}.empty{text-align:center;color:#89958e}</style>
